var internal_variable: u32 = 42;
export const p_internal_variable = &internal_variable;

extern var external_variable: u32;
export const p_external_variable = &external_variable;

// compile
// output_mode=Obj
// backend=stage2,llvm
// target=x86_64-linux

const T = struct {
    const T = struct {
        fn f() void {
            _ = T;
        }
    };
};

// error
//
// :4:17: error: ambiguous reference
// :2:5: note: declared here
// :1:1: note: also declared here

const std = @import("std");

noinline fn outer() u32 {
    var a: u32 = 42;
    _ = &a;
    return inner(.{
        .unused = a,
        .value = [1]u32{0},
    });
}

noinline fn inner(args: anytype) u32 {
    return args.value[0];
}

pub fn main() !void {
    try std.testing.expect(outer() == 0);
}

// run
// backend=stage2,llvm
// target=x86_64-linux,aarch64-linux

pub fn main() void {
    var x = null;
    _ = &x;
}

